package com.textswag.studio.collagefilters

class VisionFilter :
    BaseGlitchGPUImageFilter("uniform mat4 uMVPMatrix;attribute vec4 position;\nattribute vec4 inputTextureCoordinate;\n \nvarying vec2 textureCoordinate;\n \nvoid main()\n{\n    gl_Position = uMVPMatrix * position;\n    textureCoordinate = inputTextureCoordinate.xy;\n}", "precision highp float;\n\nvarying highp vec2 textureCoordinate;\n\nuniform sampler2D inputImageTexture;\n\nuniform highp float iTime;\n\nuniform highp vec2 inputSize;\n\nconst float FactorA = -0.02;\n\nconst float FactorB = 0.0;\n\nconst float colorScalar = 0.99;\n\n\nvec2 barrelDistortion( vec2 p, vec2 amt )\n{\n    p = 2.0 * p - 1.0;\n\n    /*\n    const float maxBarrelPower = 5.0;\n    float theta  = atan(p.y, p.x);\n    vec2 radius = vec2( length(p) );\n    radius = pow(radius, 1.0 + maxBarrelPower * amt);\n    p.x = radius.x * cos(theta);\n    p.y = radius.y * sin(theta);\n\n    /*/\n    float maxBarrelPower = sqrt(5.0);\n    float radius = dot(p,p);\n    p *= pow(vec2(radius), maxBarrelPower * amt);\n    /* */\n\n    return p * 0.5 + 0.5;\n}\n\nvec2 brownConradyDistortion(vec2 uv, float scalar)\n{\n    uv = (uv - 0.5 ) * 2.0;\n\n    if( true )\n    {\n        float barrelDistortion1 = FactorA * scalar;\n        float barrelDistortion2 = FactorB * scalar;\n\n        float r2 = dot(uv,uv);\n        uv *= 1.0 + barrelDistortion1 * r2 + barrelDistortion2 * r2 * r2;\n    }\n\n    return (uv / 2.0) + 0.5;\n}\n\nvoid main()\n{\n\n    vec2 uv = textureCoordinate.xy;\n\n\n    float maxDistort = (25.0 + iTime*80.0 / 100.0)/5.0;\n\n    float scalar = 1.0 * maxDistort;\n    vec4 colourScalar = vec4(700.0, 560.0, 490.0, 1.0);\n    colourScalar /= max(max(colourScalar.x, colourScalar.y), colourScalar.z);\n    colourScalar *= 2.0;\n\n    colourScalar *= scalar;\n\n    vec4 sourceCol = texture2D(inputImageTexture, uv);\n\n    const float numTaps = 16.;\n\n    gl_FragColor = vec4( 0.0 );\n    for( float tap = 0.0; tap < numTaps; tap += 1.0 )\n    {\n        gl_FragColor.r += texture2D(inputImageTexture, brownConradyDistortion(uv, colourScalar.r)).r;\n        gl_FragColor.g += texture2D(inputImageTexture, brownConradyDistortion(uv, colourScalar.g)).g;\n        gl_FragColor.b += texture2D(inputImageTexture, brownConradyDistortion(uv, colourScalar.b)).b;\n\n        colourScalar *= (.99+colorScalar/100.);\n    }\n\n    gl_FragColor /= numTaps;\n\n    gl_FragColor.a = 1.0;\n}"), AdjustableFilter {
    override fun setAmount(amountValue: Float) {
        setTime(amountValue)
    }
}
